     1	package surveycrawler;
     2	
     3	public class SurveyCrawler {
     4	
     5	    private Point position;
     6	    private CrawlerFacing facing;
     7	
     8	    // instance creation
     9	
    10	    public static SurveyCrawler atFacing(Point aPosition, String aFacingName) {
    11	        return new SurveyCrawler(aPosition, CrawlerFacing.facing(aFacingName));
    12	    }
    13	
    14	    public static String invalidFacingErrorDescription() {
    15	        return "Invalid facing";
    16	    }
    17	
    18	    // exceptions
    19	
    20	    public String invalidCommandErrorDescription() {
    21	        return "Invalid command";
    22	    }
    23	
    24	    public void signalInvalidCommand() {
    25	        throw new RuntimeException(invalidCommandErrorDescription());
    26	    }
    27	
    28	    // initialization
    29	
    30	    private SurveyCrawler(Point aPosition, CrawlerFacing aFacing) {
    31	        position = aPosition;
    32	        facing = aFacing;
    33	    }
    34	
    35	    // facing
    36	
    37	    public void faceRight() {
    38	        facing = new CrawlerFacingRight();
    39	    }
    40	
    41	    public void faceUp() {
    42	        facing = new CrawlerFacingUp();
    43	    }
    44	
    45	    public void faceDown() {
    46	        facing = new CrawlerFacingDown();
    47	    }
    48	
    49	    public void faceLeft() {
    50	        facing = new CrawlerFacingLeft();
    51	    }
    52	
    53	    public void turnCounterClockwise() {
    54	        facing.turnCounterClockwise(this);
    55	    }
    56	
    57	    public void turnClockwise() {
    58	        facing.turnClockwise(this);
    59	    }
    60	
    61	    // testing
    62	
    63	    public boolean isAtFacing(Point aPosition, String aFacingName) {
    64	        return position.equals(aPosition) && facing.isFacing(aFacingName);
    65	    }
    66	
    67	    public boolean isRetreatCommand(char aCommand) {
    68	        return aCommand == 't';
    69	    }
    70	
    71	    public boolean isAdvanceCommand(char aCommand) {
    72	        return aCommand == 'a';
    73	    }
    74	
    75	    public boolean isTurnCounterClockwiseCommand(char aCommand) {
    76	        return aCommand == 'g';
    77	    }
    78	
    79	    public boolean isTurnClockwiseCommand(char aCommand) {
    80	        return aCommand == 'h';
    81	    }
    82	
    83	    // moving
    84	
    85	    public void retreat() {
    86	        facing.retreat(this);
    87	    }
    88	
    89	    public void moveRight() {
    90	        position = position.plus(new Point(1, 0));
    91	    }
    92	
    93	    public void advance() {
    94	        facing.advance(this);
    95	    }
    96	
    97	    public void moveUp() {
    98	        position = position.plus(new Point(0, 1));
    99	    }
   100	
   101	    public void moveDown() {
   102	        position = position.plus(new Point(0, -1));
   103	    }
   104	
   105	    public void moveLeft() {
   106	        position = position.plus(new Point(-1, 0));
   107	    }
   108	
   109	    // command processing
   110	
   111	    public void process(String aSequenceOfCommands) {
   112	        for (char aCommand : aSequenceOfCommands.toCharArray()) {
   113	            processCommand(aCommand);
   114	        }
   115	    }
   116	
   117	    public void processCommand(char aCommand) {
   118	        if (isAdvanceCommand(aCommand)) {
   119	            advance();
   120	            return;
   121	        }
   122	        if (isRetreatCommand(aCommand)) {
   123	            retreat();
   124	            return;
   125	        }
   126	        if (isTurnClockwiseCommand(aCommand)) {
   127	            turnClockwise();
   128	            return;
   129	        }
   130	        if (isTurnCounterClockwiseCommand(aCommand)) {
   131	            turnCounterClockwise();
   132	            return;
   133	        }
   134	
   135	        signalInvalidCommand();
   136	    }
   137	}

