  8	
  9	class SurveyCrawlerTest {
 10	
 11	    @Test
 12	    void test01EmptyCommandStringDoesNothing() {
 13	        SurveyCrawler crawler = SurveyCrawler.atFacing(new Point(1, 2), "Up");
 14	
 15	        crawler.process("");
 16	
 17	        assertTrue(crawler.isAtFacing(new Point(1, 2), "Up"));
 18	    }
 19	
 20	    @Test
 21	    void test02aWhenFacingUpIncrementsY() {
 22	        SurveyCrawler crawler = SurveyCrawler.atFacing(new Point(1, 2), "Up");
 23	
 24	        crawler.process("a");
 25	
 26	        assertTrue(crawler.isAtFacing(new Point(1, 3), "Up"));
 27	    }
 28	
 29	    @Test
 30	    void test03tWhenFacingUpDecrementsY() {
 31	        SurveyCrawler crawler = SurveyCrawler.atFacing(new Point(1, 2), "Up");
 32	
